"""Plots a log generated by acessna.

Usage (from the repo root):
    uv run analysis/plot_run.py [run.csv] [--save out.png]
"""

import argparse
import csv

import matplotlib.pyplot as plt
import numpy as np

SERIES = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100"]
TEXT = "#0b0b0b"
TEXT_MUTED = "#52514e"
GRID = "#e4e3df"
SURFACE = "#fcfcfb"


def load(path):
    with open(path, newline="") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        raise SystemExit(f"{path}: no samples")
    cols = {}
    for key in rows[0]:
        # pitch_trim is blank when the controller left the trim wheel alone
        cols[key] = np.array([float(r[key]) if r[key] else np.nan for r in rows])
    return cols


def break_wraps(deg):
    """NaN out samples where an angle wraps 360 -> 0 so the line doesn't jump"""

    deg = deg.copy()
    deg[1:][np.abs(np.diff(deg)) > 180] = np.nan
    return deg


def style(ax, title, unit):
    ax.set_title(f"{title} ({unit})", loc="left", fontsize=10, color=TEXT)
    ax.grid(True, color=GRID, linewidth=0.8)
    ax.set_axisbelow(True)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(GRID)
    ax.tick_params(colors=TEXT_MUTED, labelsize=8)
    ax.ticklabel_format(axis="y", useOffset=False, style="plain")


def series(ax, t, named):
    """Plots one or more same-unit series, legend + direct labels for several"""

    for i, (name, y) in enumerate(named):
        ax.plot(t, y, color=SERIES[i], linewidth=2, label=name)
    if len(named) < 2:
        return

    # Legend sits above the plot, right-aligned
    ax.legend(loc="lower right", bbox_to_anchor=(1, 1), fontsize=8, frameon=False,
              ncol=len(named), labelcolor=TEXT_MUTED, borderaxespad=0.2)

    # Direct-label line ends unless they'd collide
    ends = [y[np.isfinite(y)][-1] for _, y in named]
    lo, hi = ax.get_ylim()
    if np.min(np.diff(np.sort(ends))) < 0.06 * (hi - lo):
        return
    for (name, _), end in zip(named, ends):
        ax.annotate(name, (t[-1], end), xytext=(4, 0), textcoords="offset points",
                    va="center", fontsize=8, color=TEXT_MUTED)


def plot(d, path):
    t = d["t"]
    fig, axs = plt.subplots(4, 2, figsize=(13, 10), facecolor=SURFACE)
    fig.suptitle(path, x=0.01, ha="left", fontsize=12, color=TEXT)

    left = axs[:, 0]
    for ax in left[1:]:
        ax.sharex(left[0])
    series(left[0], t, [("alt", d["alt_ft"])]); style(left[0], "Altitude MSL", "ft")
    series(left[1], t, [("ias", d["airspeed_kts"])]); style(left[1], "Calibrated airspeed", "kts")
    series(left[2], t, [("vs", d["vs_fpm"])]); style(left[2], "Vertical speed", "ft/min")
    series(left[3], t, [("elevator", d["elevator"]), ("aileron", d["aileron"]),
                        ("rudder", d["rudder"])])
    style(left[3], "Surfaces", "norm")
    left[3].set_xlabel("t (s)", color=TEXT_MUTED, fontsize=9)

    track = axs[0, 1]
    track.plot(d["east_m"], d["north_m"], color=SERIES[0], linewidth=2)
    track.plot(d["east_m"][0], d["north_m"][0], "o", color=SERIES[0], markersize=8,
               markeredgecolor=SURFACE, markeredgewidth=2)
    track.annotate("start", (d["east_m"][0], d["north_m"][0]), xytext=(6, 0),
                   textcoords="offset points", va="center", fontsize=8, color=TEXT_MUTED)
    track.set_aspect("equal", adjustable="datalim")
    style(track, "Ground track, north vs east", "m")

    right = axs[1:, 1]
    for ax in right[1:]:
        ax.sharex(right[0])
    right[0].sharex(left[0])
    series(right[0], t, [("heading", break_wraps(d["psi_deg"])),
                         ("track", break_wraps(d["track_deg"]))])
    style(right[0], "Heading and ground track", "deg")
    series(right[1], t, [("roll", d["phi_deg"]), ("pitch", d["theta_deg"])])
    style(right[1], "Attitude", "deg")
    series(right[2], t, [("throttle", d["throttle"])]); style(right[2], "Throttle", "norm")
    right[2].set_xlabel("t (s)", color=TEXT_MUTED, fontsize=9)

    for ax in axs.flat:
        ax.set_facecolor(SURFACE)
    fig.tight_layout()
    return fig


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("csv", nargs="?", default="run.csv")
    ap.add_argument("--save", metavar="PNG", help="write the figure instead of showing it")
    args = ap.parse_args()

    fig = plot(load(args.csv), args.csv)
    if args.save:
        fig.savefig(args.save, dpi=130, facecolor=fig.get_facecolor())
    else:
        plt.show()


if __name__ == "__main__":
    main()
